  asset_b_code: optional(pipe(string(), minLength(1), maxLength(12))),
  asset_b_issuer: optional(IsStellarAccount()),
  limit: optional(pipe(number(), integer(), minValue(1), maxValue(200)), 25),
  page: optional(pipe(number(), integer(), minValue(0)), 0),
});
export type FetchClassicLiquidityPoolsParamsOutput = InferOutput<typeof FetchClassicLiquidityPoolsParamsSchema>;

export type AssetOutput = InferOutput<typeof AssetSchema>;
export const AssetSchema = object({
  id: IsStellarContract(),
  code: string(),
  issuer: nullable(IsStellarAccount()),
  name: string(),
  org: string(),
  domain: string(),
  icon: string(),
  decimals: number(),
});
export type AssetInput = InferInput<typeof AssetSchema>;

export type AssetBalanceInput = InferInput<typeof AssetBalanceSchema>;
export const AssetBalanceSchema = object({
  contract: IsStellarAddress(),
  balance: union([pipe(string(), toBigint(), bigint()), bigint()]),
  is_classic: boolean(),
  trust_line: nullable(object({
    balance: union([pipe(string(), toBigint(), bigint()), bigint()]),
    selling: union([pipe(string(), toBigint(), bigint()), bigint()]),
    buying: union([pipe(string(), toBigint(), bigint()), bigint()]),
    limit: union([pipe(string(), toBigint(), bigint()), bigint()]),
    is_authorized: boolean(),
    can_maintain_liabilities: boolean(),
    clawback_enabled: boolean(),
    is_revoked: boolean(),
  })),
});
export type AssetBalanceOutput = InferOutput<typeof AssetBalanceSchema>;

export type NftInput = InferInput<typeof NftSchema>;
export const NftSchema = object({
  id: IsStellarAddress(),
  description: string(),
  name: string(),
  symbol: string(),
  base_uri: string(),
});
export type NftOutput = InferOutput<typeof NftSchema>;

export type NftBalanceInput = InferInput<typeof NftBalanceSchema>;
export const NftBalanceSchema = object({
  contract: IsStellarAddress(),
  balance: union([pipe(string(), toBigint(), bigint()), bigint()]),
  owned: array(union([pipe(string(), toBigint(), bigint()), pipe(number(), toBigint(), bigint()), bigint()])),
});
export type NftBalanceOutput = InferOutput<typeof NftBalanceSchema>;

import { array, parse, parseAsync } from "jsr:@valibot/valibot@1.4.1";
import {
  type AccountOutput,
  AccountSchema,
  type AssetBalanceInput,
  type AssetBalanceOutput,
  AssetBalanceSchema,
  type AssetInput,
  type AssetOutput,
  AssetSchema,
  type ClassicDataOutput,
  ClassicDataSchema,
  type ClassicLiquidityPoolDataInput,
  type ClassicLiquidityPoolDataOutput,
  ClassicLiquidityPoolDataSchema,
  type ContractData,
  ContractDataSchema,
  type FetchClassicLiquidityPoolsParamsInput,
  type FetchClassicLiquidityPoolsParamsOutput,
  FetchClassicLiquidityPoolsParamsSchema,
  type FetchContractDataBodyInput,
  type FetchContractDataBodyOutput,
  FetchContractDataBodySchema,
  type NftBalanceInput,
  type NftBalanceOutput,
  NftBalanceSchema,
  type NftInput,
  type NftOutput,
  NftSchema,
  type StellarIndexerSdkParamsInput,
  type StellarIndexerSdkParamsOutput,
  StellarIndexerSdkParamsSchema,
  type TrustLineOutput,
  TrustLineSchema,
} from "./schemas.ts";
import wretch from "npm:wretch@3.0.8";
import QueryStringAddon from "npm:/wretch@3.0.8/addons/queryString";
import initWASM from "npm:@stellar/stellar-xdr-json@^28.0.0";
import { Networks } from "npm:@stellar/stellar-sdk@^17.0.1";

/**
 * Base class for the Stellar Indexer SDK.
 * This class will be the simplest part of the library and from this base the "extensions" can be created.
 * The base class is the one who takes care of sending the requests to the API and to handle the authentication side.
 */
export class StellarIndexerSdk {
  #apiUrl: string;
  #consumerToken: string;
  #skipWASM: boolean;
  #wasmStarted: boolean = false;

  get api() {
    return wretch(this.#apiUrl).addon(QueryStringAddon).headers({ "authorization": `Bearer ${this.#consumerToken}` });
  }

  constructor(params?: StellarIndexerSdkParamsInput) {
    const parsed: StellarIndexerSdkParamsOutput = parse(StellarIndexerSdkParamsSchema, params);
    if (parsed.apiUrl) {
      this.#apiUrl = parsed.apiUrl;
    } else {
      this.#apiUrl = parsed.network === Networks.PUBLIC ? "https://api.stellarindexer.com" : "https://api-testnet.stellarindexer.com";
    }
    this.#consumerToken = parsed.consumerToken;
    this.#skipWASM = parsed.skipWASM;
  }

  async startWasm(): Promise<void> {
    if (this.#skipWASM || this.#wasmStarted) return;
    await initWASM();
    this.#wasmStarted = true;
  }

  /**
   * This method calls the `contract-data` endpoint and parses the response
   *
   * REQUIRES: Access to the Contract Data package
   *
   * @param params {FetchContractDataBodyInput}
   * @param params.contract_id - The contract id to search
   * @param params.key - an array of key objects
   * @param params.val - an array of val objects (This one is only taken in consideration when there is a provided "key")
   * @param params.limit - The amount of records to get (default 25)
   * @param params.page - The current page of the records, it starts at 0
   * @param params.sort - Either desc or asc (default "desc")
   * @param params.orderBy - Either `timestamp` or `none` (default timestamp)
   */
  async fetchContractData(params: FetchContractDataBodyInput): Promise<ContractData[]> {
    await this.startWasm();
    const payload: FetchContractDataBodyOutput = parse(FetchContractDataBodySchema, params);
    const result: unknown[] = await this.api.url("/v1/contract-data/").post(payload).json();
    return await Promise.all(result.map((r) => parseAsync(ContractDataSchema, r)));
  }

  /**
   * REQUIRES: Access to the Classic Data package
   *
   * @param id - The account public key
   */
  async fetchAccount(id: string): Promise<AccountOutput> {
    await this.startWasm();
    const result: ClassicLiquidityPoolDataInput = await this.api.url(`/v1/classic-data/accounts/${id}`).get().json();
    return await parseAsync(AccountSchema, result);
  }

  /**
   * REQUIRES: Access to the Classic Data package
   *
   * @param id - The account public key
   */
  async fetchAccountTrustLines(id: string): Promise<TrustLineOutput[]> {
    await this.startWasm();
    const result: ClassicLiquidityPoolDataInput = await this.api.url(`/v1/classic-data/accounts/${id}/trust-lines`).get().json();
    return await parseAsync(array(TrustLineSchema), result);
  }

  /**
   * REQUIRES: Access to the Classic Data package
   *
   * @param id - The account public key
   */
  async fetchAccountData(id: string): Promise<ClassicDataOutput[]> {
    await this.startWasm();
    const result: ClassicLiquidityPoolDataInput = await this.api.url(`/v1/classic-data/accounts/${id}/data`).get().json();
    return await parseAsync(array(ClassicDataSchema), result);
  }

  /**
   * Method to query classic liquidity pools based on the assets provided, you can query by just one asset or both;
   * You can query by just the asset code or be more specific by also providing the asset issuers.
   *
   * REQUIRES: Access to the Classic Data package
   *
   * @param params {FetchClassicLiquidityPoolsParamsInput}
   * @param params.asset_a_code - The asset code of the asset A, it can be "XLM" or any other valid classic Asset code
   * @param params.asset_a_issuer - The issuer of the asset A; for the native XLM you should keep this undefined
   * @param params.asset_b_code - The asset code of the asset B, it can be "XLM" or any other valid classic Asset code
   * @param params.asset_b_issuer - The issuer of the asset B; for the native XLM you should keep this undefined
   * @param params.limit - The amount of records to get (default 25)
   * @param params.page - The current page of the records, it starts at 0
   */
  async fetchClassicLiquidityPools(params: FetchClassicLiquidityPoolsParamsInput): Promise<ClassicLiquidityPoolDataOutput[]> {
    await this.startWasm();
    const payload: FetchClassicLiquidityPoolsParamsOutput = parse(FetchClassicLiquidityPoolsParamsSchema, params);
    const result: ClassicLiquidityPoolDataInput[] = await this.api.url("/v1/classic-data/liquidity-pools").query(payload).get().json();
    return await parseAsync(array(ClassicLiquidityPoolDataSchema), result);
  }

  /**
   * REQUIRES: Access to the Classic Data package
   *
   * @param id - The pool id
   */
  async fetchClassicLiquidityPoolById(id: string): Promise<ClassicLiquidityPoolDataOutput> {
    await this.startWasm();
    const result: ClassicLiquidityPoolDataInput = await this.api.url(`/v1/classic-data/liquidity-pools/${id}`).get().json();
    return await parseAsync(ClassicLiquidityPoolDataSchema, result);
  }

  /**
   * REQUIRES: Access to the Assets Balances package
   *
   * This method will get the assets the platform tracks fors balances.
   *
   * NOTE: TrustLines are not limited to these assets IE when getting TrustLines balances, all of them will be returned even if they are not tracked assets
   */
  async fetchAssets(): Promise<AssetOutput[]> {
    await this.startWasm();
    const result: AssetInput[] = await this.api.url(`/v1/balances/tracked/assets`).get().json();
    return await parseAsync(array(AssetSchema), result);
  }

  /**
   * REQUIRES: Access to the Assets Balances package
   *
   * This method will get the NFTs the platform tracks fors balances.
   */
  async fetchNfts(): Promise<NftOutput[]> {
    await this.startWasm();
    const result: NftInput[] = await this.api.url(`/v1/balances/tracked/nfts`).get().json();
    return await parseAsync(array(NftSchema), result);
  }

  /**
   * REQUIRES: Access to the Assets Balances package
   *
   * @param id - Either a Stellar Classic account (G address) or a Smart Account (C address)
   */
  async getAccountAssetsBalances(id: string): Promise<AssetBalanceOutput[]> {
    await this.startWasm();
    const result: AssetBalanceInput[] = await this.api.url(`/v1/balances/users/${id}/assets`).get().json();
    return await parseAsync(array(AssetBalanceSchema), result);
  }

  /**
   * REQUIRES: Access to the Assets Balances package
   *
   * @param id - Either a Stellar Classic account (G address) or a Smart Account (C address)
   */
  async getAccountNftsBalances(id: string): Promise<NftBalanceOutput[]> {
    await this.startWasm();
    const result: NftBalanceInput[] = await this.api.url(`/v1/balances/users/${id}/nfts`).get().json();
    return await parseAsync(array(NftBalanceSchema), result);
  }
}
